def transform(grid):
    """Color 3 between the outermost marker cells in each row and column."""
    from collections import Counter
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    marker = next(v for v in counts if v != bg)
    for r in range(h):
        positions = [c for c, v in enumerate(grid[r]) if v == marker]
        if len(positions) >= 2:
            for c in range(positions[0] + 1, positions[-1]):
                if out[r][c] == bg:
                    out[r][c] = 3
    for c in range(w):
        positions = [r for r in range(h) if grid[r][c] == marker]
        if len(positions) >= 2:
            for r in range(positions[0] + 1, positions[-1]):
                if out[r][c] == bg:
                    out[r][c] = 3
    return out
